mapper.select:
select id, symbol, security_name, instrument_type, side, traded_at, quantity, price, total_fee, status, strategy, tags, industry_code, industry_name
  from cynexus_appl_market.portfolio_trade
 where principal_key = #{principalKey} and tenant_key = #{tenantKey}
   and deleted_at is null

   and symbol = #{symbol}

 order by traded_at, id

select id, symbol, security_name, instrument_type, side, traded_at, quantity, price, total_fee, status, strategy, tags, industry_code, industry_name
  from cynexus_appl_market.portfolio_trade
 where id = #{tradeId}
   and principal_key = #{principalKey}
   and tenant_key = #{tenantKey}
   and deleted_at is null
